// Des: Start the app: read args and config, open state, open the browser only if needed
// Flo: args > aa-conf-main.json > state dir + db > (login, run, ask) launch own-profile Chrome + tab > dispatch > close everything
// I/O: process Init (caller) > exit code 0-4; browser profile in prof_dirz_path, state in stat_dirz_path
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig"); const targ = @import("ct-ctrl-args.zig"); const runz = @import("ct-ctrl-runz.zig"); const task = @import("ru-task-runn.zig"); const stat = @import("st-stat-main.zig"); const chro = @import("nt-brow-chro.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig");
const CF = .{ .file = "aa-conf-main.json", .cand = [_][]const u8{ "..", "../..", "." }, .dbfi = "fb-state.db", .boot = 30000, .conn = 8000, .help = "fb: Facebook helper that works like you, at a human pace.\n  fb status [--json]          caps, warm-up, quiet hours, last stop\n  fb login                    open the browser, log in by hand once\n  fb run <job> [flags]        jobs: post page dm join friend reply list renew renewall sold\n  fb ask \"<words>\"            e.g. \"post: hello\" | \"reply to my comments\" | \"renew my listings\"\n  fb ledger | log [--json]    Marketplace ledger | recent actions\n  fb pause | resume           stop or allow running jobs\n  fb unlock <key>             clear an unsure key after you checked Facebook\nflags: --text --to --url --title --price --desc --group --photo --max N --conf <file> --head (hidden browser)\nsafety: default is a dry-run preview. --read = read only. --live = do it. --live --force = also approve risky acts.\nexit: 0 ok | 1 failed | 2 usage | 3 page changed | 4 blocked (quiet hours, cap, challenge, approval)" };
fn confFind(allo: std.mem.Allocator, iozz: std.Io, args: targ.Args) !cfgz.Conf { if (args.conf.len > 0) return cfgz.confLoad(allo, iozz, args.conf); const dirz = std.process.executableDirPathAlloc(iozz, allo) catch "."; for (CF.cand) |rela| { const path = std.fs.path.join(allo, &.{ dirz, rela, CF.file }) catch continue; _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch continue; return cfgz.confLoad(allo, iozz, path); } return .{}; }
fn outz(iozz: std.Io, text: []const u8) void { std.Io.File.stdout().writeStreamingAll(iozz, text) catch {}; }
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); const iozz = init.io; var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); const args = try targ.argsRead(argv.items); if (args.helz or args.cmdz.len == 0 or std.mem.eql(u8, args.cmdz, "help")) { outz(iozz, CF.help ++ "\n"); return if (args.cmdz.len == 0 and !args.helz) 2 else 0; }
const conf = try confFind(allo, iozz, args); const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse ""; const sdir = cfgz.pathExpa(allo, home, conf.stat_dirz_path) catch return error.BadConfig; try std.Io.Dir.cwd().createDirPath(iozz, sdir); const dbp = try std.fs.path.joinZ(allo, &.{ sdir, CF.dbfi }); var store = try stat.Stat.open(allo, dbp); defer store.close();
var seed = conf.rand_seed_numb; if (seed == 0) { var sb: [8]u8 = undefined; iozz.random(&sb); seed = std.mem.readInt(u64, &sb, .little); } var rng = pace.Rng.init(seed); var page: pg.Page = undefined; var brow: ?chro.Brow = null; defer if (brow) |*brw| brw.stop(); var opened = false; defer if (opened) page.closeConn();
if (runz.needBrow(args.cmdz)) { const exe = (try chro.exeFind(allo, iozz, conf.brow_exec_path)) orelse return error.NoBrowser; const prof = cfgz.pathExpa(allo, home, conf.prof_dirz_path) catch return error.BadConfig; brow = chro.launch(allo, iozz, exe, prof, conf.brow_head_mode or args.head, CF.boot) catch return error.BrowFail; const wsp = try chro.pageWs(allo, iozz, brow.?.port, CF.boot); page = try pg.pageOpen(allo, iozz, brow.?.port, wsp, CF.conn); opened = true; page.arm(conf.brow_time_seco * 1000); try page.enable(allo); }
var ctx: task.Ctx = .{ .gpaz = init.gpa, .aren = allo, .iozz = iozz, .conf = conf, .store = &store, .mode = args.mode(), .page = &page, .rng = &rng, .base = conf.base_urlz_main }; return runz.dispatch(&ctx, args); }
